-- READ-ONLY exact six-timestamp episode/context SELECT; Q1 2018 and 2021 excluded.
SELECT o.dateTime,o.`interval` AS old_interval,o.outTemp AS old_temp,w.`interval` AS wh_interval,w.outTemp AS wh_temp,e.outTemp AS eu_temp,g.outTemp AS gw_temp,eo.outTemp AS eu_old_temp,r.outTemp AS recon_temp,l.temperature_c AS luhamet_temp,l.relative_humidity_pct AS luhamet_rh FROM old_weewx.archive o LEFT JOIN weewx_WH1080.archive w ON w.dateTime=o.dateTime LEFT JOIN `pocasi-loucka.eu`.archive e ON e.dateTime=o.dateTime LEFT JOIN `pocasi-loucka.eu_GW1000`.archive g ON g.dateTime=o.dateTime LEFT JOIN `pocasi-loucka.eu_old`.archive eo ON eo.dateTime=o.dateTime LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=o.dateTime LEFT JOIN loucka_reconstruction.reference_observations l ON l.station_id='luhamet_sehradice' AND l.observed_at_utc=o.dateTime WHERE o.dateTime BETWEEN 1474276200 AND 1474277700 ORDER BY o.dateTime;
